import{_ as r,a0 as a,w as d,s as m,ao as i,I as n,x as p,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"命令列星期二——第四部分 | LCTT x X-CMD","titleTemplate":false,"description":"命令列星期二——第四部分 | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令列星期二——第四部分 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令列星期二——第四部分 | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140709 Command Line Tuesdays--Part Four","title":"命令列星期二——第四部分","tag":"201407","desc":""},"relativePath":"201407/20140709 Command Line Tuesdays--Part Four.md","filePath":"[post].md"}'),l={name:"201407/20140709 Command Line Tuesdays--Part Four.md"};function u(f,e,c,T,g,C){const t=a("Link");return d(),m("div",null,[e[11]||(e[11]=i('<h1 id="命令列星期二——第四部分" tabindex="-1">命令列星期二——第四部分 <a class="header-anchor" href="#命令列星期二——第四部分" aria-label="Permalink to “命令列星期二——第四部分”">​</a></h1><p>大家好。新的一週，新的冒險！</p><p>今天，我們將會學習使用四個相當簡單的命令去操作文件。好，廢話少説，我們開始吧。</p><p>在開始學習這些命令之前，我們先稍微説些題外話，講講“通配符”的用處。</p><p>###通配符###</p><p>使用圖形工具區複製、粘貼、新建目錄等操作也許很容易，但是若想完成一些更復雜的任務，例如僅僅將一個目錄下的所有.html文件複製到另一個目錄中、或者只複製在某個目錄中不存在的文件，這時命令列也許會比較方便。我們回到通配符的學習中，通配符是shell的基本功能，它是一個由一些特殊字符組成的集合，它讓你可以用一些簡單的規則來選擇出某些文件。（通配符可以出現在文件名中，用於指定文件名的字符個數和字母的大/小寫等規則）。</p><p>如下表 ：</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/07/Screenshot-08.-07.-2014-125946.png" alt=""></p><p>下面是肖茨先生給出的一些實例，如下表：</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/07/Screenshot-08.-07.-2014-125959.png" alt=""></p><p>如果你使用一個包含文件名參數的命令，你就可以使用通配符。</p><p>###cp###</p><p>cp是一個用於複製文件或者目錄的命令，它的用法相當的簡單。進入到你想複製的文件所在的目錄，然後使用如下命令</p><p><code>cp file1 file2</code> -複製一個文件</p><p>或者</p><p><code>cp file1 file2 ... directory</code> -從當前工作目錄複製多個文件到指定的目錄。</p><p>下表是肖茨先生給出的cp命令的一些選項：</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/07/Screenshot-08.-07.-2014-134248.png" alt=""></p><p>###mv###</p><p>mv是今天的第二個命令，我們可以使用mv來重命名一個文件或目錄，或者移動一個文件或目錄。我們可以這樣使用mv命令。</p><p><code>mv filename1 filename2</code> -若想將文件filename1重命名為filename2。</p><p>或者</p><p><code>mv file directory</code> -若想將一個文件移動到某個目錄。</p><p>下表是一些mv命令的實例</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/07/Screenshot-08.-07.-2014-133515.png" alt=""></p><p>###rm###</p><p>rm命令是用於刪除文件或目錄，它的用法比較直接，如下：</p><p><code>rm file</code></p><p>或者</p><p><code>rm -r driectory</code></p><p>這裏也有一個包含rm其他選項的表</p><p><img src="https://news.opensuse.org/wp-content/uploads/2014/07/Screenshot-08.-07.-2014-133529.png" alt=""></p><p>但是，使用rm命令時要小心點。因為並沒有撤銷刪除的選項，因此使用rm命令式要格外的小心，避免對你的系統造成不必要的破壞。</p><p>###mkdir###</p><p>mkdir是用於創建目錄.它是今天最簡單的一個命令：</p><p><code>mkdir directory</code></p><p>看，目錄成功創建了！</p><p>這是本週的內容，下週二再見，致以最真誠的問候！</p><hr>',39)),n("p",null,[e[1]||(e[1]=p("via: ",-1)),o(t,{href:"https://news.opensuse.org/2014/07/08/command-line-tuesdays-part-four/"},{default:s(()=>[...e[0]||(e[0]=[p("https://news.opensuse.org/2014/07/08/command-line-tuesdays-part-four/",-1)])]),_:1})]),n("p",null,[e[4]||(e[4]=p("譯者：",-1)),o(t,{href:"https://github.com/cvsher"},{default:s(()=>[...e[2]||(e[2]=[p("cvsher",-1)])]),_:1}),e[5]||(e[5]=p(" 校對：",-1)),o(t,{href:"https://github.com/wxy"},{default:s(()=>[...e[3]||(e[3]=[p("wxy",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=p("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[6]||(e[6]=[p("LCTT",-1)])]),_:1}),e[9]||(e[9]=p(" 原創翻譯，",-1)),o(t,{href:"http://linux.cn/"},{default:s(()=>[...e[7]||(e[7]=[p("Linux中國",-1)])]),_:1}),e[10]||(e[10]=p(" 榮譽推出",-1))])])}const L=r(l,[["render",u]]);export{x as __pageData,L as default};
